<?php require_once __DIR__.'/../config/config.php';
$u=require_role(['parent','student']);if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method không hợp lệ'],405);$code=strtoupper(trim($_POST['connection_code']??''));$st=db()->prepare('SELECT * FROM students WHERE connection_code=?');$st->execute([$code]);$s=$st->fetch();if(!$s)json_response(['success'=>false,'message'=>'Mã kết nối không hợp lệ.'],422);
if($u['role']==='parent'){$st=db()->prepare('INSERT IGNORE INTO student_parents(student_id,parent_id) VALUES(?,?)');$st->execute([$s['id'],$u['id']]);}else{$st=db()->prepare('SELECT user_id FROM student_accounts WHERE student_id=?');$st->execute([$s['id']]);$existing=$st->fetchColumn();if($existing!==false&&(int)$existing!==$u['id'])json_response(['success'=>false,'message'=>'Học sinh này đã có tài khoản.'],409);$st=db()->prepare('INSERT INTO student_accounts(student_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)');$st->execute([$s['id'],$u['id']]);}json_response(['success'=>true,'student'=>$s]);
